function onLoad() {
    //Type appropriate comment here, and begin script below

    g_form.clearOptions('area_of_injury_box');

    if (g_lang === "en") {
        g_form.addOption('area_of_injury_box', '', 'Please select..');

        g_form.addOption('area_of_injury_box', 'Abdomen', 'Abdomen');
        g_form.addOption('area_of_injury_box', 'Ankle', 'Ankle');
        g_form.addOption('area_of_injury_box', 'Arm', 'Arm');
        g_form.addOption('area_of_injury_box', 'Brain', 'Brain');
        g_form.addOption('area_of_injury_box', 'Chest', 'Chest');
