        g_form.addOption('area_of_injury_box', 'Teeth', 'Teeth');
        g_form.addOption('area_of_injury_box', 'Thigh', 'Thigh');
        g_form.addOption('area_of_injury_box', 'Toes', 'Toes');
        g_form.addOption('area_of_injury_box', 'Upper back', 'Upper back');
        g_form.addOption('area_of_injury_box', 'Wrist', 'Wrist');
        g_form.addOption('area_of_injury_box', 'Other', 'Other');
    }

    if (g_lang === "fq") {
        g_form.addOption('area_of_injury_box', '', 'Veuillez sélectionner..');

        g_form.addOption('area_of_injury_box', 'Abdomen', 'Abdomen');
