        g_form.addOption('area_of_injury_box', 'Bas de la jambe', 'Bas de la jambe');
        g_form.addOption('area_of_injury_box', 'Bas du dos', 'Bas du dos');
        g_form.addOption('area_of_injury_box', 'Bassin', 'Bassin');
        g_form.addOption('area_of_injury_box', 'Bras', 'Bras');
        g_form.addOption('area_of_injury_box', 'Cerveau', 'Cerveau');
        g_form.addOption('area_of_injury_box', 'Cheville', 'Cheville');
        g_form.addOption('area_of_injury_box', 'Cou', 'Cou');
        g_form.addOption('area_of_injury_box', 'Coude', 'Coude');
        g_form.addOption('area_of_injury_box', 'Cuisse', 'Cuisse');
